+const getSigningKey = (): Buffer => {
+  const key = process.env.SESSION_SIGNING_KEY;
+  if (!key) {
+    throw new Error("SESSION_SIGNING_KEY environment variable must be set");
+  }
+  return Buffer.from(key, "base64");
+};
+
 export const loadSession = async (id: string): Promise<Session | null> => {
   const result = await pool.query(
     "SELECT id, user_id, revoked_at FROM sessions WHERE id = $1",
@@ -19,3 +28,41 @@ export const loadSession = async (id: string): Promise<Session | null> => {
 export const revokeSession = async (id: string): Promise<void> => {
   await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
 };
+
+export const signSessionToken = (session: Session): string => {
+  const key = getSigningKey();
+  const payload = JSON.stringify({
+    id: session.id,
+    userId: session.userId,
+  });
+
+  const hmac = createHmac("sha256", key);
+  hmac.update(payload);
+  const signature = hmac.digest("base64url");
+
+  return `${Buffer.from(payload).toString("base64url")}.${signature}`;
+};
+
+export interface ValidatedSession {
+  id: string;
+  userId: string;
+}
+
+export const validateSessionToken = (token: string): ValidatedSession | null => {
+  try {
+    const [payloadEncoded, signature] = token.split(".");
+    if (!payloadEncoded || !signature) return null;
+
+    const key = getSigningKey();
+    const hmac = createHmac("sha256", key);
+    hmac.update(payloadEncoded);
+    const expectedSignature = hmac.digest("base64url");
+
+    if (signature !== expectedSignature) return null;
+
+    const payload = JSON.parse(Buffer.from(payloadEncoded, "base64url").toString());
+    return { id: payload.id, userId: payload.userId };
+  } catch {
+    return null;
+  }
+};
