@@ -0,0 +1,26 @@
+import { Session, signSessionToken, validateSessionToken } from "./src/session-store.ts";
+import { randomBytes } from "crypto";
+
+// Generate a test signing key
+const testKey = randomBytes(32).toString("base64");
+process.env.SESSION_SIGNING_KEY = testKey;
+
+const testSession: Session = {
+  id: "sess_12345",
+  userId: "user_789",
+  revokedAt: null,
+};
+
+console.log("Original session:", testSession);
+
+const token = signSessionToken(testSession);
+console.log("\nSigned token:", token);
+
+const validated = validateSessionToken(token);
+console.log("\nValidated from token:", validated);
+
+const tampered = token + "x";
+const tamperedResult = validateSessionToken(tampered);
+console.log("\nTampered token validation (should be null):", tamperedResult);
+
+console.log("\nSuccess! Token validation works at the edge.");
